const xlsx = global.get('xlsx');  // Asume que xlsx está disponible globalmente, si no, asegúrate de que se importe correctamente

// Recoger las variables del contexto de flujo
const variables = {
    num: flow.get('num'),
    active: flow.get('active'),
    cajaString: flow.get('cajaString'),
    eui: flow.get('eui'),
    harness: flow.get('harness'),
    inversor: flow.get('inversor'),
    powerStation: flow.get('powerStation'),
    ubicacion: flow.get('ubicacion'),
    msgDailyCounter: flow.get('msgDailyCounter'),
    data_corriente1: flow.get('data_corriente1'),
    data_corriente2: flow.get('data_corriente2'),
    data_corriente3: flow.get('data_corriente3'),
    data_corriente4: flow.get('data_corriente4'),
    rssi: flow.get('rssi')
};

// Convertir el objeto de variables a un arreglo de arreglos (AoA)
const worksheetData = [];

// Encabezados de las columnas
const headers = Object.keys(variables);
worksheetData.push(headers);

// Valores de las variables
const values = headers.map(key => variables[key]);
worksheetData.push(values);

// Crear una hoja de cálculo
const workbook = xlsx.utils.book_new();
const worksheet = xlsx.utils.aoa_to_sheet(worksheetData);
xlsx.utils.book_append_sheet(workbook, worksheet, "Data");

// Escribir el archivo
const filePath = "C:/Users/{{ruta_archivo}}/report-node-red.xlsx";  // Ruta donde se guardará el archivo
xlsx.writeFile(workbook, filePath);

msg.payload = `Archivo creado en ${filePath}`;
return msg;

